import{_ as e,o as n,c as a,a2 as s}from"./chunks/framework.BEmfQga0.js";const p=JSON.parse('{"title":"Core Runtime","description":"","frontmatter":{},"headers":[],"relativePath":"platform-concepts/core-runtime.md","filePath":"platform-concepts/core-runtime.md","lastUpdated":1788258471000}'),i={name:"platform-concepts/core-runtime.md"};function o(r,t,l,d,c,g){return n(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="core-runtime" tabindex="-1">Core Runtime <a class="header-anchor" href="#core-runtime" aria-label="Permalink to &quot;Core Runtime&quot;">​</a></h1><p>The LightRSI core runtime is the <strong>host-independent execution engine</strong> that loads, manages, and runs plugins. It sits between the agent host and the plugins, providing a consistent environment regardless of which host the user is running.</p><h2 id="responsibilities" tabindex="-1">Responsibilities <a class="header-anchor" href="#responsibilities" aria-label="Permalink to &quot;Responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Responsibility</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Plugin loading</strong></td><td style="text-align:left;">Discovers, validates, and loads plugins from configured directories</td></tr><tr><td style="text-align:left;"><strong>Lifecycle management</strong></td><td style="text-align:left;">Calls plugin hooks at the right time: install, enable, session start, session end, disable, uninstall</td></tr><tr><td style="text-align:left;"><strong>Configuration</strong></td><td style="text-align:left;">Merges host config, plugin config, and user overrides into a resolved configuration</td></tr><tr><td style="text-align:left;"><strong>Event routing</strong></td><td style="text-align:left;">Dispatches host events (messages, tool calls, session state changes) to plugins</td></tr><tr><td style="text-align:left;"><strong>Resource isolation</strong></td><td style="text-align:left;">Ensures plugins cannot interfere with each other or the host</td></tr></tbody></table><h2 id="current-implementation" tabindex="-1">Current Implementation <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Current Implementation&quot;">​</a></h2><p>The core runtime is implemented across these workspace packages:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Package</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>components/packages/foundation/kernel</code></td><td style="text-align:left;">Shared types, interfaces, events, and runtime contracts</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/runtime-core</code></td><td style="text-align:left;">Host-agnostic runtime engine and shared execution logic</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/host-adapter</code></td><td style="text-align:left;">Shared host-adapter contracts and path-resolution interfaces</td></tr><tr><td style="text-align:left;"><code>components/packages/foundation/history</code></td><td style="text-align:left;">Canonical state, raw semantic turns, task registry</td></tr><tr><td style="text-align:left;"><code>components/packages/features/eviction</code></td><td style="text-align:left;">Policy analysis, reduction/eviction decisions, estimator</td></tr><tr><td style="text-align:left;"><code>components/packages/features/memory</code> <span class="badge-experimental">experimental</span></td><td style="text-align:left;">Distillation and retrieval (in progress)</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/platform-concepts/plugins">Plugins</a> — how plugins are structured</li><li><a href="/LightRSI/platform-concepts/plugin-lifecycle">Plugin Lifecycle</a> — the plugin state machine</li><li><a href="/LightRSI/platform-concepts/host-adapters">Host Adapters</a> — how hosts connect</li></ul>',9)])])}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
